// Decide, para cada producto de Lococo, si hay que CREARLO o ACTUALIZARLO en tu tienda,
// y qué productos tuyos ya no están en la lista (DESACTIVAR). El emparejamiento es por modelo.
const scr = $('Scrapear Lococo').first().json;
const raw = $('Mis productos').all().map(i => i.json);
const mine = (raw.length === 1 && Array.isArray(raw[0].products) ? raw[0].products : raw).filter(p => p && p.id);
const bool = (v, d) => v === undefined || v === '' ? d : String(v).toLowerCase() === 'true';
const DEACT = bool($env.DEACTIVATE_MISSING, true);
const MIN_SCRAPE = Number($env.MIN_SCRAPE_COUNT || 800);
const MAX_DET = Number($env.DETAILS_MAX_PER_RUN || 300);
const K = s => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');

const items = scr.items || [];
if (items.length < MIN_SCRAPE) {
  throw new Error(`Lococo devolvió ${items.length} productos (mínimo esperado ${MIN_SCRAPE}). Freno para no desactivar tu catálogo por un scraping roto.`);
}

const byKey = new Map();
for (const p of mine) { const k = K(p.model); if (k) { if (!byKey.has(k)) byKey.set(k, []); byKey.get(k).push(p); } }

const plan = [];
const used = new Set();
const pending = [];
// 1) Modelo exacto (sin importar guiones, espacios ni mayúsculas)
for (const s of items) {
  const hits = byKey.get(K(s.code)) || [];
  if (hits.length) { hits.forEach(p => used.add(p.id)); plan.push({ op: 'update', s, products: hits, match_type: 'exacto' }); }
  else pending.push(s);
}
// 2) Un modelo contiene al otro (ej. HAC-B1A21P dentro de DH-HAC-B1A21P-U-0280B), solo si hay un único candidato libre
for (const s of pending) {
  const k = K(s.code);
  const cands = k.length >= 6 && s.model_source !== 'generado'
    ? mine.filter(p => !used.has(p.id) && K(p.model).length >= 6 && (K(p.model).includes(k) || k.includes(K(p.model))))
    : [];
  if (cands.length === 1) { used.add(cands[0].id); plan.push({ op: 'update', s, products: cands, match_type: 'contiene' }); }
  else plan.push({ op: 'create', s, products: [], match_type: 'nuevo' });
}
// 3) Productos tuyos que ya no están en Lococo
const missing = mine.filter(p => !used.has(p.id) && K(p.model));
if (DEACT) for (const p of missing) if (p.active !== false) plan.push({ op: 'deactivate', s: null, products: [p], match_type: 'no está en Lococo' });

// Fichas a bajar: primero los nuevos, después los que tienen la ficha incompleta
const needs = [];
for (const e of plan.filter(e => e.op === 'create')) needs.push(e.s.search);
for (const e of plan.filter(e => e.op === 'update'))
  if (e.products.some(p => !(p.specs && p.specs.length) || !p.category)) needs.push(e.s.search);
const need_details = [...new Set(needs)].slice(0, MAX_DET);

return [{ json: {
  plan, need_details,
  stats: {
    lococo: items.length, mios: mine.length,
    crear: plan.filter(e => e.op === 'create').length,
    actualizar: plan.filter(e => e.op === 'update').length,
    desactivar: plan.filter(e => e.op === 'deactivate').length,
    duplicados: plan.filter(e => e.products.length > 1).map(e => ({ modelo: e.s.code, productos: e.products.map(p => p.sku || p.id) })),
    sin_modelo_en_tu_tienda: mine.filter(p => !K(p.model)).length,
    fichas_pedidas: need_details.length, fichas_pendientes: Math.max(0, new Set(needs).size - need_details.length),
  },
} }];

// Parte las fichas en tandas: cada tanda es un request corto al scraper (si una falla, no se pierde todo)
const codes = $input.first().json.need_details || [];
const size = Number($env.DETAILS_CHUNK || 40);
const out = [];
for (let i = 0; i < codes.length; i += size) out.push({ json: { codes: codes.slice(i, i + size), tanda: out.length + 1 } });
return out.length ? out : [{ json: { codes: [], tanda: 0 } }];

// Arma lo que se manda a tu tienda. Precio y stock se actualizan siempre;
// nombre, marca, categoría, ficha y foto solo se completan si están vacíos (salvo OVERWRITE_CONTENT=true).
const { plan, stats } = $('Planificar').first().json;
const fichas = $('Fichas Lococo').all().map(i => i.json || {});
const det = { items: fichas.flatMap(f => f.items || []), errors: fichas.flatMap(f => f.errors || []) };
const scr = $('Scrapear Lococo').first().json;
const bool = (v, d) => v === undefined || v === '' ? d : String(v).toLowerCase() === 'true';
const num = (v, d) => v === undefined || v === '' || isNaN(Number(v)) ? d : Number(v);

const TARGET = String($env.TARGET_CURRENCY || 'USD').toUpperCase();
const MARGIN = num($env.PRICE_MARGIN_PCT, 0);
const IVA = num($env.ADD_IVA_PCT, 0);
const ROUND = num($env.PRICE_ROUND_TO, 0.01);
const MAX_CHANGE = num($env.MAX_CHANGE_PCT, 30);
const RATE = num($env.USD_RATE, 0) || scr.usd_rate || 0;
const OVERWRITE = bool($env.OVERWRITE_CONTENT, false);
const PUBLISH_NEW = bool($env.PUBLISH_NEW, true);
const ONLY_WITH_DETAILS = bool($env.CREATE_ONLY_WITH_DETAILS, true);
const IN_STOCK = String($env.IN_STOCK_STATUSES || 'inmediato,deposito_2,tercer_deposito').split(',').map(s => s.trim());
const TITLE = String($env.NAME_STYLE || 'title').toLowerCase() === 'title';

const details = new Map((det.items || []).map(d => [d.code, d]));
const round2 = n => Math.round(n * 100) / 100;

function price(s) {
  let p = s.price;
  const cur = String(s.currency || 'USD').toUpperCase();
  if (cur !== TARGET) {
    if (!RATE) return null;
    p = cur === 'USD' ? p * RATE : p / RATE;
  }
  p = p * (1 + IVA / 100) * (1 + MARGIN / 100);
  return ROUND > 1 ? Math.round(p / ROUND) * ROUND : round2(p);
}

const ACR = new Set(['IP','PTZ','DVR','NVR','XVR','HD','UTP','FTP','POE','HDMI','VGA','USB','LED','IR','RFID','AHD','TVI','CVI','HDCVI','WDR','ONVIF','SD','PIR','GSM','LTE','4G','UPS','RJ45','CAT','DC','AC','PVC','OEM','2K','4K','DVR/NVR','NFC','SIM','LAN','WAN','SSD','HDD','MP','MM','TB','GB','MB','MBPS','GBPS','MHZ','GHZ','W','V','VA','AH','KVA','M','U','CM','FPS','DB','IP65','IP66','IP67']);
const LOW = new Set(['DE','DEL','CON','Y','A','PARA','EN','SIN','O','LA','EL','LOS','LAS','POR','X']);
function nice(name) {
  if (!TITLE) return name;
  return name.split(' ').map((w, i) => w.split('-').map(p => {
    const U = p.toUpperCase();
    if (!p || /\d/.test(p) || ACR.has(U) || /^[^A-ZÁÉÍÓÚÑ]+$/i.test(p)) return U;
    if (i > 0 && LOW.has(U)) return p.toLowerCase();
    return p.charAt(0).toUpperCase() + p.slice(1).toLowerCase();
  }).join('-')).join(' ').replace(/\s·\s/g, ' · ');
}
const descOf = (name, specs) => specs.length ? `${name}.\n\nCaracterísticas:\n${specs.map(x => '- ' + x).join('\n')}` : name;
const empty = v => v === null || v === undefined || v === '' || (Array.isArray(v) && !v.length);

const out = [];
const postergados = [];
for (const e of plan) {
  if (e.op === 'deactivate') {
    const p = e.products[0];
    out.push({ json: { op: 'deactivate', match: { id: p.id }, data: { active: false, inStock: false }, label: p.sku || p.model, motivo: e.match_type } });
    continue;
  }
  const s = e.s;
  const d = details.get(s.search);
  const specs = d?.specs || [];
  const category = d?.category || null;
  const imageUrl = d?.image_url || s.image_url || null;
  const name = nice(s.raw_name);
  const newPrice = price(s);
  const stockStatus = s.stock_status;
  const inStock = IN_STOCK.includes(stockStatus);

  if (e.op === 'create') {
    if (newPrice === null) { postergados.push({ modelo: s.code, motivo: 'sin cotización para convertir moneda' }); continue; }
    if (!d && ONLY_WITH_DETAILS) { postergados.push({ modelo: s.code, motivo: 'ficha pendiente (se crea en la próxima corrida)' }); continue; }
    out.push({ json: { op: 'create', match: null, label: s.code, motivo: 'nuevo en Lococo', data: {
      model: s.code, sku: s.code, name, description: descOf(name, specs), brand: s.brand, category,
      price: newPrice, stockStatus, inStock, active: PUBLISH_NEW, specs, imageUrl,
    } } });
    continue;
  }

  // update: puede haber más de un producto tuyo con el mismo modelo (duplicados) -> se actualizan todos
  for (const p of e.products) {
    const data = {};
    let review = null;
    if (newPrice !== null && newPrice !== Number(p.price)) {
      const pct = Number(p.price) > 0 ? Math.abs(newPrice - p.price) / p.price * 100 : 0;
      if (pct > MAX_CHANGE) review = `precio ${p.price} -> ${newPrice} (${pct.toFixed(0)}%)`;
      else data.price = newPrice;
    }
    if (p.stockStatus !== stockStatus) data.stockStatus = stockStatus;
    if (p.inStock !== inStock) data.inStock = inStock;
    if (p.active === false) data.active = true;  // volvió a la lista de Lococo
    const fill = (k, v) => { if (!empty(v) && (OVERWRITE ? JSON.stringify(p[k]) !== JSON.stringify(v) : empty(p[k]))) data[k] = v; };
    fill('brand', s.brand);
    fill('category', category);
    fill('specs', specs);
    fill('imageUrl', imageUrl);
    if (specs.length) fill('description', descOf(OVERWRITE ? name : (p.name || name), specs));
    if (OVERWRITE) fill('name', name);
    if (!Object.keys(data).length && !review) continue;  // sin cambios
    out.push({ json: { op: 'update', match: { id: p.id }, data, label: p.sku || s.code, motivo: e.match_type,
                       review, duplicado: e.products.length > 1 } });
  }
}
// Un item extra con el resumen del plan (no se manda a la tienda)
out.push({ json: { op: 'resumen', stats, postergados, fichas_con_error: det.errors || [] } });
return out;

// DRY_RUN=true: no manda nada. Si no, agrupa de a BATCH_SIZE operaciones por request
if (String($env.DRY_RUN).toLowerCase() !== 'false') return [];
const ops = $input.all().map(i => i.json).filter(o => o.op !== 'resumen' && Object.keys(o.data || {}).length);
const size = Number($env.BATCH_SIZE || 50);
const out = [];
for (let i = 0; i < ops.length; i += size) out.push({ json: { items: ops.slice(i, i + size).map(({ op, match, data }) => ({ op, match, data })),
                                                            labels: ops.slice(i, i + size).map(o => o.label) } });
return out;

const lotes = $('Agrupar en lotes').all();
const plan = $('Armar operaciones').all().map(i => i.json);
const head = plan.find(o => o.op === 'resumen') || {};
const tally = {}; const errores = [];
$input.all().forEach((it, i) => {
  const sc = it.json.statusCode;
  const labels = lotes[i]?.json.labels || [];
  if (sc !== 200) { errores.push({ lote: i + 1, status: sc, error: it.json.body?.error ?? it.json.body ?? null }); return; }
  (it.json.body?.results || []).forEach((r, j) => {
    tally[r.status] = (tally[r.status] || 0) + 1;
    if (r.status === 'error' || r.warning) errores.push({ producto: labels[j] ?? r.model ?? r.id, error: r.error || r.warning });
  });
});
return [{ json: {
  resultado: tally,
  errores,
  revisar_a_mano: plan.filter(o => o.review).map(o => ({ producto: o.label, motivo: o.review })),
  duplicados_en_tu_tienda: head.stats?.duplicados || [],
  postergados: { total: (head.postergados || []).length, ejemplos: (head.postergados || []).slice(0, 20) },
  fichas_con_error: head.fichas_con_error || [],
  plan: head.stats || {},
} }];
